--
-- Table structure for table `students`
--

DROP TABLE IF EXISTS `students`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `students` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `center_id` bigint(20) unsigned NOT NULL,
  `name` varchar(255) NOT NULL,
  `fathers_name` varchar(255) NOT NULL,
  `mothers_name` varchar(255) NOT NULL,
  `roll` varchar(255) DEFAULT NULL,
  `registration` varchar(255) DEFAULT NULL,
  `date_of_birth` varchar(255) NOT NULL,
  `exam_date` date DEFAULT NULL,
  `gender` tinyint(3) unsigned NOT NULL,
  `blood_group` tinyint(3) unsigned DEFAULT NULL,
  `religion` tinyint(3) unsigned NOT NULL,
  `present_address` varchar(255) NOT NULL,
  `permanent_address` varchar(255) NOT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `password` varchar(255) NOT NULL DEFAULT '$2y$10$F9f/uGOarW9190BDZsgXXecIA0T50AmL.JQAULlnpySFMvbsxjVSK',
  `email` varchar(255) DEFAULT NULL,
  `course_duration` varchar(255) DEFAULT NULL,
  `qualification` varchar(255) DEFAULT NULL,
  `guardian_name` varchar(255) DEFAULT NULL,
  `nid_or_birth` varchar(255) DEFAULT NULL,
  `session_id` bigint(20) unsigned NOT NULL,
  `subject_id` bigint(20) unsigned NOT NULL,
  `picture` varchar(255) DEFAULT NULL,
  `passport` varchar(255) DEFAULT NULL,
  `status` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `due_amount` decimal(8,2) unsigned NOT NULL DEFAULT 0.00,
  `paid_amount` decimal(8,2) unsigned NOT NULL DEFAULT 0.00,
  `remember_token` varchar(100) DEFAULT NULL,
  `result_publised` timestamp NULL DEFAULT NULL,
  `course_type` int(10) unsigned NOT NULL DEFAULT 0,
  `payment_status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '1=Paid, 0=Unpaid',
  PRIMARY KEY (`id`),
  KEY `students_center_id_foreign` (`center_id`),
  KEY `students_session_id_foreign` (`session_id`),
  KEY `students_subject_id_foreign` (`subject_id`),
  CONSTRAINT `students_center_id_foreign` FOREIGN KEY (`center_id`) REFERENCES `centers` (`id`),
  CONSTRAINT `students_session_id_foreign` FOREIGN KEY (`session_id`) REFERENCES `sessions` (`id`),
  CONSTRAINT `students_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5362 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

